)

// asyncEventRuntime mimics the production Adapter.StartRun behavior:
// it returns the result while a background goroutine is still delivering
// OnEvent callbacks (see internal/platform/runtime/runtime.go:331-401).
type asyncEventRuntime struct {
	delay time.Duration
}

func (r *asyncEventRuntime) StartRun(_ context.Context, req pruntime.Request) (pruntime.Result, error) {
	done := make(chan struct{})
	go func() {
		defer close(done)
		for i := 0; i < 50; i++ {
			time.Sleep(r.delay)
			if req.OnEvent != nil {
				req.OnEvent(pruntime.Event{SessionID: "async-session"})
			}
		}
	}()
	// Return without waiting for the pump to finish, like the 1s abandon path.
	return pruntime.Result{RunID: "run", SessionID: "", Status: "success", Artifacts: []pruntime.Artifact{{ID: "e", Kind: "test", Description: "verified"}}}, errors.New("") == nil /* placeholder */ && false || func() bool { <-time.After(2 * r.delay); return true }()
}

