)

// R1c: resume runs remaining tasks against the CURRENTLY resolved target while
// the persisted header keeps the previous run's Target verbatim.
func TestScratchResumeRunsNewTargetButPersistsStaleHeader(t *testing.T) {
	runtime := &modelProbeRuntime{}
	root, sp, service := executePersistenceFixture(t, runtime)

	plan := strings.Replace(validPlan(), "## Evidence Checklist",
		"- [ ] Task 2: Second unit for Decision 1 / AC-01\n  > Executes: Decision 1, AC-01\n  - [ ] Verification expectation: go test ./...\n\n## Evidence Checklist", 1)
	writeFileContent(t, sp.Path, plan, "plan.md")

	if _, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{}); err != nil {
		t.Fatalf("run1: %v", err)
	}
	state, err := LoadExecuteRunState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("run1: tasks=%d statuses=%v target=%q", len(state.Tasks), statusesOf(state), state.Target.Path)
	// Simulate an interrupted second task from an earlier environment.
	for i := range state.Tasks {
		if strings.Contains(state.Tasks[i].Identity.Name, "Task 2") {
			state.Tasks[i].Status = ExecuteTaskPending
		}
	}
	state.Target.Path = "/somewhere/stale/old-target"
	if err := SaveExecuteRunState(root, sp, state); err != nil {
		t.Fatal(err)
	}

	runtime.requests = nil
	result, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{Resume: true})
	if err != nil {
		t.Fatalf("resume: %v", err)
	}
	for _, req := range runtime.requests {
		t.Logf("resume ran WorkDir=%q mode=%q", req.WorkDir, req.Metadata["execution_session_mode"])
	}
	after, _ := LoadExecuteRunState(root, sp)
	t.Logf("post-resume: persisted Target=%q message=%q statuses=%v", after.Target.Path, result.Message, statusesOf(after))
}

func statusesOf(s ExecuteRunState) []string {
	out := []string{}
	for _, t := range s.Tasks {
		out = append(out, string(t.Status))
	}
	return out
}
