package sprint

import (
	"context"
	"strings"
	"testing"
)

type deletingRuntime struct {
	modelProbeRuntime
	deleted []string
}

func (r *deletingRuntime) DeleteSession(_ context.Context, id string) error {
	r.deleted = append(r.deleted, id)
	return nil
}

// P4: successful --task run records + deletes its session; later full resume
// still selects that session for continuation.
func TestScratchSessionDeletedButRecordedForReuse(t *testing.T) {
	runtime := &deletingRuntime{}
	root, sp, service := executePersistenceFixture(t, runtime)

	plan := strings.Replace(validPlan(), "## Evidence Checklist",
		"- [ ] Task 2: Second unit for Decision 1 / AC-01\n  > Executes: Decision 1, AC-01\n  - [ ] Verification expectation: go test ./...\n\n## Evidence Checklist", 1)
	writeFileContent(t, sp.Path, plan, "plan.md")

	first := validPlanTask1ID(t, service)
	if _, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{TaskID: first}); err != nil {
		t.Fatalf("single-task run: %v", err)
	}
	state, err := LoadExecuteRunState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	var recorded string
	for _, task := range state.Tasks {
		if task.Runtime != nil && task.Runtime.SessionID != "" {
			recorded = task.Runtime.SessionID
		}
	}
	t.Logf("recorded session=%q deleted sessions=%v", recorded, runtime.deleted)

	// Resume selection logic without needing a live runtime:
	reused := reusableExecuteSession(state.Tasks, "", "test/model")
	t.Logf("resume would reuse session=%q (deleted=%v)", reused, containsStr(runtime.deleted, reused))
}

func validPlanTask1ID(t *testing.T, s Service) string {
	t.Helper()
	_, _, _, _, findings, err := s.prepareExecute("proj", "01", ExecuteRequest{})
	if err != nil || len(findings) > 0 {
		t.Fatalf("prepare: %v %v", err, findings)
	}
	return firstTaskID(t, s)
}

func firstTaskID(t *testing.T, s Service) string {
	t.Helper()
	sp := Sprint{Project: "proj", Slug: "01-alpha"}
	inputs, err := s.store.ReadPlanningInputs(sp)
	if err != nil {
		t.Fatal(err)
	}
	catalog, pf := projectParseForProbe(s, inputs)
	if len(pf) > 0 {
		t.Fatalf("catalog findings %v", pf)
	}
	manifest, findings := s.planManifest(sp, inputs, catalog)
	if len(findings) > 0 {
		t.Fatalf("manifest %v", findings)
	}
	data, err := s.store.ReadArtifact(sp, StagePlan)
	if err != nil {
		t.Fatal(err)
	}
	tasks, findings := extractExecutePlanTasks(data, manifest, false)
	if len(findings) > 0 || len(tasks) == 0 {
		t.Fatalf("extract %v", findings)
	}
	return tasks[0].ID
}

func containsStr(list []string, v string) bool {
	for _, item := range list {
		if item == v {
			return true
		}
	}
	return false
}
EOF
