type deletingRuntime struct {
	requests []pruntime.Request
	deleted  []string
}

func (r *deletingRuntime) StartRun(_ context.Context, req pruntime.Request) (pruntime.Result, error) {
	r.requests = append(r.requests, req)
	if req.OnEvent != nil {
		req.OnEvent(pruntime.Event{SessionID: "sess-1"})
	}
	return pruntime.Result{RunID: "run-" + req.Metadata["task"], SessionID: "sess-1", Status: "success",
		Artifacts: []pruntime.Artifact{{ID: "evidence", Kind: "test", Description: "verified"}}}, nil
}

func (r *deletingRuntime) DeleteSession(_ context.Context, id string) error {
	r.deleted = append(r.deleted, id)
	return nil
}

func TestScratchSessionDeletedButRecordedForReuse(t *testing.T) {
	runtime := &deletingRuntime{}
	root, sp, service := executePersistenceFixture(t, runtime)

	plan := strings.Replace(validPlan(), "## Evidence Checklist",
		"- [ ] Task 2: Second unit for Decision 1 / AC-01\n  > Executes: Decision 1, AC-01\n  - [ ] Verification expectation: go test ./...\n\n## Evidence Checklist", 1)
	writeFileContent(t, sp.Path, plan, "plan.md")

	inputs, err := service.store.ReadPlanningInputs(sp)
	if err != nil {
		t.Fatal(err)
	}
	catalog, _ := project.ParseProjectIndex(inputs.ProjectIndex)
	manifest, mf := service.planManifest(sp, inputs, catalog)
	if len(mf) > 0 {
		t.Fatalf("manifest %v", mf)
	}
	data, err := service.store.ReadArtifact(sp, StagePlan)
	if err != nil {
		t.Fatal(err)
	}
	tasks, ef := extractExecutePlanTasks(data, manifest, false)
	if len(ef) > 0 || len(tasks) == 0 {
		t.Fatalf("extract %v", ef)
	}

	if _, err := service.Execute(context.Background(), "proj", "01", ExecuteRequest{TaskID: tasks[0].ID}); err != nil {
		t.Fatalf("single-task run: %v", err)
	}
	state, err := LoadExecuteRunState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	var recorded string
	for _, task := range state.Tasks {
		if task.Runtime != nil && task.Runtime.SessionID != "" {
			recorded = task.Runtime.SessionID
		}
	}
	t.Logf("recorded session=%q deleted=%v pendingRemaining=%t", recorded, runtime.deleted, anyPending(state))

	reused := reusableExecuteSession(state.Tasks, "", "test/model")
